                        <span style="margin-right: 1rem; margin-left: 1rem; color: white">{{ $paginator->firstItem() }}</span>
                        {!! __('to') !!}
                        <span style="margin-right: 1rem; margin-left: 1rem">{{ $paginator->lastItem() }}</span>
                    @else
                        {{ $paginator->count() }}
                    @endif
                    {!! __('of') !!}
                    <span style="margin-right: 1rem; margin-left: 1rem">{{ $paginator->total() }}</span>
                    {!! __('results') !!}
                </p>
